/** Native PDF paragraphs, figures and verified cell grids in their source geometry. */
final class LayoutWordExporter {
 static String xml(String s){return s.replaceAll("[\\x00-\\x08\\x0B\\x0C\\x0E-\\x1F]","").replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;");}
 static class Line{String text,font;float x,y,w,h,size;boolean rtl;}
 static class Picture{float x,y,w,h;}
 static final class PageData{double width,height;JSONObject structure;Bitmap raster;void close(){if(raster!=null)raster.recycle();}}
 static JSONObject block(String type,String text,float x,float y,float w,float h,double pageW,double pageH,double size)throws Exception{return new JSONObject().put("type",type).put("text",text).put("x",Math.max(0,x/pageW)).put("y",Math.max(0,y/pageH)).put("w",Math.max(.0001,Math.min(w,pageW-x)/pageW)).put("h",Math.max(.0001,Math.min(h,pageH-y)/pageH)).put("fontSize",Math.max(4,Math.min(96,size))).put("rows",0).put("columns",0).put("cells",new JSONArray()).put("columnWidths",new JSONArray());}
 static boolean bold(Line l){return l.font!=null&&l.font.toLowerCase(Locale.ROOT).contains("bold");}
 static boolean italic(Line l){return l.font!=null&&l.font.toLowerCase(Locale.ROOT).matches(".*(italic|oblique).*");}
 static String font(Line l){return l.font!=null&&l.font.toLowerCase(Locale.ROOT).contains("times")?"Times New Roman":"Arial";}
 static List<Line> rows(List<Line> input){List<Line> sorted=new ArrayList<>(input);sorted.sort(Comparator.comparingDouble(l->l.y+l.h/2));List<Line> out=new ArrayList<>();
  for(Line l:sorted){Line merge=null;for(int i=out.size()-1;i>=0;i--){Line a=out.get(i);if(l.y-a.y>a.h*2)break;float gap=Math.max(a.x,l.x)-Math.min(a.x+a.w,l.x+l.w);if(a.rtl==l.rtl&&bold(a)==bold(l)&&Math.abs(a.size-l.size)<Math.max(1,a.size*.2)&&Math.abs((a.y+a.h/2)-(l.y+l.h/2))<Math.min(a.h,l.h)*.35&&gap<Math.max(a.size,l.size)*1.5&&gap>-Math.min(a.w,l.w)*.4){merge=a;break;}}
   if(merge==null){out.add(l);continue;}Line a=merge;boolean before=l.rtl?l.x>a.x:l.x<a.x;float gap=before?(l.rtl?l.x-(a.x+a.w):a.x-(l.x+l.w)):(l.rtl?a.x-(l.x+l.w):l.x-(a.x+a.w));String space=gap>Math.min(a.size,l.size)*.12?" ":"";a.text=before?l.text+space+a.text:a.text+space+l.text;float right=Math.max(a.x+a.w,l.x+l.w),bottom=Math.max(a.y+a.h,l.y+l.h);a.x=Math.min(a.x,l.x);a.y=Math.min(a.y,l.y);a.w=right-a.x;a.h=bottom-a.y;
  }out.sort(Comparator.comparingDouble(l->l.y));return out;
 }
 static JSONArray paragraphs(List<Line> input,double width,double height,List<Picture> images)throws Exception{
  List<Line> lines=rows(input);List<List<Line>> groups=new ArrayList<>();for(Line line:lines){List<Line> target=null;for(int i=groups.size()-1;i>=0;i--){List<Line> g=groups.get(i);Line last=g.get(g.size()-1);float gap=line.y-(last.y+last.h),overlap=Math.min(line.x+line.w,last.x+last.w)-Math.max(line.x,last.x);boolean figure=false;for(Picture p:images)if(p.y>=last.y+last.h-1&&p.y+p.h<=line.y+1&&p.x<line.x+line.w&&p.x+p.w>line.x){figure=true;break;}if(!figure&&gap>=-1&&gap<=Math.max(last.size,line.size)*.85&&line.rtl==last.rtl&&bold(line)==bold(last)&&italic(line)==italic(last)&&Math.abs(line.size-last.size)<=Math.max(1,last.size*.12)&&overlap>=Math.min(line.w,last.w)*.6){target=g;break;}}if(target==null){target=new ArrayList<>();groups.add(target);}target.add(line);}
  JSONArray blocks=new JSONArray();for(List<Line> group:groups){float x=Float.MAX_VALUE,y=Float.MAX_VALUE,right=0,bottom=0;StringBuilder text=new StringBuilder();JSONArray runs=new JSONArray();for(Line l:group){x=Math.min(x,l.x);y=Math.min(y,l.y);right=Math.max(right,l.x+l.w);bottom=Math.max(bottom,l.y+l.h);String value=(text.length()>0?"\n":"")+l.text;text.append(value);runs.put(new JSONObject().put("text",value).put("bold",bold(l)).put("italic",italic(l)).put("font",font(l)));}Line first=group.get(0);double blockWidth=Math.min(width-x,Math.max(right-x+3,first.size*2));JSONObject b=block("text",text.toString(),x,Math.max(0,y-1),(float)blockWidth,bottom-y+4,width,height,first.size).put("runs",runs).put("font",font(first)).put("bold",bold(first)).put("italic",italic(first));double center=x+blockWidth/2;b.put("alignment",group.size()==1&&Math.abs(center-width/2)<width*.025&&blockWidth<width*.8?"center":first.rtl?"right":"left");blocks.put(b);}return blocks;
 }
 static JSONObject table(WordTables.Table t,double width,double height)throws Exception{
  JSONObject b=block("table","",t.xs[0],t.ys[0],t.xs[t.cols]-t.xs[0],t.ys[t.rows]-t.ys[0],width,height,12).put("rows",t.rows).put("columns",t.cols);JSONArray cells=new JSONArray(),widths=new JSONArray();for(int c=0;c<t.cols;c++)widths.put((t.xs[c+1]-t.xs[c])/(double)(t.xs[t.cols]-t.xs[0]));
  for(int i=0;i<t.parent.length;i++)if(t.root(i)==i){int minR=t.rows,maxR=-1,minC=t.cols,maxC=-1;for(int j=0;j<t.parent.length;j++)if(t.root(j)==i){minR=Math.min(minR,j/t.cols);maxR=Math.max(maxR,j/t.cols);minC=Math.min(minC,j%t.cols);maxC=Math.max(maxC,j%t.cols);}StringBuilder text=new StringBuilder();for(Line l:rows(t.cells[i])){if(text.length()>0)text.append('\n');text.append(l.text);}cells.put(new JSONObject().put("row",minR).put("column",minC).put("rowSpan",maxR-minR+1).put("columnSpan",maxC-minC+1).put("text",text));}return b.put("cells",cells).put("columnWidths",widths);
 }
 static PointF point(PDPage page,float x,float y){float px=x-page.getCropBox().getLowerLeftX(),py=y-page.getCropBox().getLowerLeftY(),w=page.getCropBox().getWidth(),h=page.getCropBox().getHeight();switch((page.getRotation()%360+360)%360){case 90:return new PointF(py,px);case 180:return new PointF(w-px,py);case 270:return new PointF(h-py,w-px);default:return new PointF(px,h-py);}}
 static PageData analyze(Context c,PDDocument doc,File source,int number,String language,boolean forceOcr)throws Exception{return analyze(c,doc,source,number,language,forceOcr,true);}
 static PageData analyze(Context c,PDDocument doc,File source,int number,String language,boolean forceOcr,boolean recognizeRaster)throws Exception{
  PDPage page=doc.getPage(number-1);PageData result=new PageData();boolean rotated=Math.abs(page.getRotation()%180)==90;result.width=rotated?page.getCropBox().getHeight():page.getCropBox().getWidth();result.height=rotated?page.getCropBox().getWidth():page.getCropBox().getHeight();double width=result.width,height=result.height;List<Line> lines=new ArrayList<>();List<Picture> pictures=new ArrayList<>();List<WordTables.Rule> rules=new ArrayList<>();
  PDFTextStripper stripper=new PDFTextStripper(){@Override protected void writeString(String text,List<TextPosition> positions)throws IOException{super.writeString(text,positions);if(text.isBlank()||positions.isEmpty())return;Line l=new Line();l.text=TextQuality.clean(text);l.x=Float.MAX_VALUE;l.y=Float.MAX_VALUE;float right=0,bottom=0;l.size=positions.get(0).getFontSizeInPt();l.font=positions.get(0).getFont().getName();for(TextPosition p:positions){l.x=Math.min(l.x,p.getXDirAdj());l.y=Math.min(l.y,p.getYDirAdj()-p.getHeightDir());right=Math.max(right,p.getXDirAdj()+p.getWidthDirAdj());bottom=Math.max(bottom,p.getYDirAdj());}l.w=right-l.x;l.h=Math.max(l.size*1.1f,bottom-l.y+2);l.rtl=CloudDocuments.isRtl(l.text);if(l.x>=0&&l.y>=0&&l.x<width&&l.y<height&&!l.text.isEmpty())lines.add(l);}};stripper.setSortByPosition(true);stripper.setStartPage(number);stripper.setEndPage(number);String raw=stripper.getText(doc);
  PDFGraphicsStreamEngine graphics=new PDFGraphicsStreamEngine(page){PointF current=new PointF(),begin=new PointF();List<WordTables.Rule> path=new ArrayList<>();void rule(float x,float y,float a,float b){PointF p=point(page,x,y),q=point(page,a,b);path.add(new WordTables.Rule(p.x,p.y,q.x,q.y));}
   public void drawImage(PDImage image)throws IOException{if(pictures.size()>=30)return;Matrix m=getGraphicsState().getCurrentTransformationMatrix();float[] xy={0,0,1,0,1,1,0,1};float left=Float.MAX_VALUE,top=Float.MAX_VALUE,right=0,bottom=0;for(int i=0;i<xy.length;i+=2){PointF p=m.transformPoint(xy[i],xy[i+1]);PointF q=point(page,p.x,p.y);left=Math.min(left,q.x);top=Math.min(top,q.y);right=Math.max(right,q.x);bottom=Math.max(bottom,q.y);}left=Math.max(0,left);top=Math.max(0,top);right=Math.min((float)width,right);bottom=Math.min((float)height,bottom);if(right-left<2||bottom-top<2)return;if(right-left>=width*.92&&bottom-top>=height*.92)return;Picture p=new Picture();p.x=left;p.y=top;p.w=right-left;p.h=bottom-top;pictures.add(p);}
   public void appendRectangle(PointF a,PointF b,PointF d,PointF e){rule(a.x,a.y,b.x,b.y);rule(b.x,b.y,d.x,d.y);rule(d.x,d.y,e.x,e.y);rule(e.x,e.y,a.x,a.y);}public void clip(Path.FillType n){}public void moveTo(float x,float y){current.set(x,y);begin.set(x,y);}public void lineTo(float x,float y){rule(current.x,current.y,x,y);current.set(x,y);}public void curveTo(float a,float b,float d,float e,float f,float g){current.set(f,g);}public PointF getCurrentPoint(){return current;}public void closePath(){rule(current.x,current.y,begin.x,begin.y);current.set(begin.x,begin.y);}public void endPath(){path.clear();}public void strokePath(){rules.addAll(path);path.clear();}public void fillPath(Path.FillType n){path.clear();}public void fillAndStrokePath(Path.FillType n){rules.addAll(path);path.clear();}public void shadingFill(COSName name){}};graphics.processPage(page);
  boolean raster=forceOcr||!TextQuality.usable(raw,language);if(raster||!pictures.isEmpty())try(ParcelFileDescriptor fd=ParcelFileDescriptor.open(source,ParcelFileDescriptor.MODE_READ_ONLY);PdfRenderer renderer=new PdfRenderer(fd)){result.raster=PdfProcessor.render(renderer,number-1,2600);}
  if(raster)lines.clear();if(raster&&recognizeRaster){try(ArabicOcr ocr=new ArabicOcr(c)){for(ArabicOcr.Line found:ocr.read(result.raster)){Line l=new Line();l.text=found.text;l.font="Arial";l.x=(float)(found.box.left*width/result.raster.getWidth());l.y=(float)(found.box.top*height/result.raster.getHeight());l.w=(float)(found.box.width()*width/result.raster.getWidth());l.h=(float)(found.box.height()*height/result.raster.getHeight());l.size=Math.max(6,l.h*.67f);l.rtl=CloudDocuments.isRtl(l.text);lines.add(l);}}rules.addAll(RasterRules.detect(result.raster,(float)width,(float)height));}
  // Text inside an embedded figure stays in that figure, including hidden OCR
  // overlays. Captions outside its physical bounds remain editable paragraphs.
  lines.removeIf(l->{for(Picture p:pictures){float ix=Math.max(0,Math.min(l.x+l.w,p.x+p.w)-Math.max(l.x,p.x)),iy=Math.max(0,Math.min(l.y+l.h,p.y+p.h)-Math.max(l.y,p.y));if(ix*iy>=l.w*l.h*.85)return true;}return false;});
  rules.removeIf(r->{for(Picture p:pictures)if(r.x1>=p.x-1&&r.x2<=p.x+p.w+1&&r.y1>=p.y-1&&r.y2<=p.y+p.h+1)return true;return false;});
  List<WordTables.Table> tables=WordTables.detect(rules);List<Line> outside=new ArrayList<>();for(Line line:lines){boolean cell=false;for(WordTables.Table t:tables)if(t.add(line)){cell=true;break;}if(!cell)outside.add(line);}JSONArray blocks=paragraphs(outside,width,height,pictures);for(WordTables.Table t:tables)blocks.put(table(t,width,height));for(Picture p:pictures)blocks.put(block("image","",p.x,p.y,p.w,p.h,width,height,12));result.structure=new JSONObject().put("blocks",blocks);return result;
 }
 static File export(Context c,File source,int first,int last)throws Exception{return export(c,source,first,last,"ara+eng",false,true);}
 static File export(Context c,File source,int first,int last,String language,boolean forceOcr)throws Exception{return export(c,source,first,last,language,forceOcr,true);}
 static File export(Context c,File source,int first,int last,String language,boolean forceOcr,boolean positioned)throws Exception{
  PDFBoxResourceLoader.init(c);File output=FilesUtil.output(c,"docx");try(PDDocument doc=PDDocument.load(source);ZipOutputStream zip=new ZipOutputStream(new FileOutputStream(output))){if(first<1||last<first||last>doc.getNumberOfPages()||last-first>=20)throw new IOException("اختر نطاقًا لا يتجاوز 20 صفحة");StringBuilder body=new StringBuilder(),rels=new StringBuilder();int blocks=0;for(int n=first;n<=last;n++){PageData data=analyze(c,doc,source,n,language,forceOcr);try{blocks+=data.structure.getJSONArray("blocks").length();body.append(EditableWord.page(zip,data.structure,data.raster,data.width,data.height,n,positioned));rels.append(EditableWord.relationships(data.structure,n));body.append(EditableWord.section(data.width,data.height,n==last,positioned));if(body.length()>4000000||output.length()>80L*1024*1024)throw new IOException("المستند كبير جدًا؛ اختر صفحات أقل");}finally{data.close();}}if(blocks==0)throw new IOException("لم يُعثر على نص أو صور قابلة للاستخراج");EditableWord.finish(zip,body,rels);return output;}catch(Exception|OutOfMemoryError e){output.delete();throw e;}
 }
 static File image(Context c,File source,boolean positioned)throws Exception{
  File output=FilesUtil.output(c,"docx");Bitmap bitmap=FilesUtil.image(source,3000);double width=595.28,height=width*bitmap.getHeight()/bitmap.getWidth();try(ArabicOcr ocr=new ArabicOcr(c);ZipOutputStream zip=new ZipOutputStream(new FileOutputStream(output))){List<Line> lines=new ArrayList<>();for(ArabicOcr.Line found:ocr.read(bitmap)){Line l=new Line();l.text=found.text;l.font="Arial";l.x=(float)(found.box.left*width/bitmap.getWidth());l.y=(float)(found.box.top*height/bitmap.getHeight());l.w=(float)(found.box.width()*width/bitmap.getWidth());l.h=(float)(found.box.height()*height/bitmap.getHeight());l.size=Math.max(6,l.h*.67f);l.rtl=CloudDocuments.isRtl(l.text);lines.add(l);}if(lines.isEmpty())throw new IOException("لم يُعثر على نص واضح في الصورة");JSONObject page=new JSONObject().put("blocks",paragraphs(lines,width,height,Collections.emptyList()));StringBuilder body=new StringBuilder(EditableWord.page(zip,page,bitmap,width,height,1,positioned)).append(EditableWord.section(width,height,true,positioned));EditableWord.finish(zip,body,new StringBuilder());return output;}catch(Exception|OutOfMemoryError e){output.delete();throw e;}finally{bitmap.recycle();}
 }
 static String style(float x,float y,float w,float h){return String.format(Locale.US,"position:absolute;margin-left:%.2fpt;margin-top:%.2fpt;width:%.2fpt;height:%.2fpt;mso-position-horizontal-relative:page;mso-position-vertical-relative:page",x,y,w,h);}
 static void entry(ZipOutputStream zip,String name,String text)throws IOException{entry(zip,name,text.getBytes(java.nio.charset.StandardCharsets.UTF_8));}static void entry(ZipOutputStream zip,String name,byte[] bytes)throws IOException{zip.putNextEntry(new ZipEntry(name));zip.write(bytes);zip.closeEntry();}
}
